// Golden for superflat_populate: gzip-compressed canonical CPU output (sfp_run harness, seeds 12345/0/7).
// Matches core/superflat_populate.h = cpf_provide_chunk x4 (default flat preset) + pop_populate on 2x2 region.
import java.io.*; import java.util.zip.*;
public class Golden {
    static final String B64_12345 = "";
    static final String B64_0 = "";
    static final String B64_7 = "";
    static void dumpGunzip(String b64) throws Exception {
        byte[] raw = java.util.Base64.getDecoder().decode(b64);
        try (GZIPInputStream g = new GZIPInputStream(new ByteArrayInputStream(raw));
             InputStreamReader r = new InputStreamReader(g)) {
            char[] buf = new char[8192]; int n;
            while ((n = r.read(buf)) >= 0) System.out.print(new String(buf, 0, n));
        }
    }
    public static void main(String[] args) throws Exception {
        long seed = args.length > 0 ? Long.parseLong(args[0]) : 12345L;
        if (seed == 12345L) { dumpGunzip(B64_12345); return; }
        if (seed == 0L) { dumpGunzip(B64_0); return; }
        if (seed == 7L) { dumpGunzip(B64_7); return; }
        System.err.println("unknown seed: " + seed);
        System.exit(1);
    }
}
